namespace Inventory;

/// <summary>Builds a replenishment plan across a set of stock items.</summary>
public sealed class ReplenishmentPlanner
{
    public IReadOnlyList<string> BuildPlan(IEnumerable<StockItem> items, ISupplier supplier, int season)
    {
        var plan = new List<string>();
        foreach (var item in items)
        {
            if (TryCreatePlanEntry(item, supplier, season, out var entry))
                plan.Add(entry);
        }

        return plan;
    }

    private static bool TryCreatePlanEntry(
        StockItem item,
        ISupplier supplier,
        int season,
        out string entry)
    {
        entry = string.Empty;
        if (!RequiresReplenishment(item))
            return false;

        int available = item.OnHand - item.Reserved;
        int orderQuantity = ApplySeasonalAdjustment(
            CalculateOrderQuantity(item.ReorderPoint - available),
            season);

        if (orderQuantity <= 0 || string.IsNullOrEmpty(item.Sku))
            return false;

        bool placed = supplier.PlaceOrder(item.Sku, orderQuantity);
        entry = FormatPlanEntry(item.Sku, orderQuantity, placed);
        return true;
    }

    private static bool RequiresReplenishment(StockItem item)
    {
        if (item.OnHand < 0)
            return false;

        int available = item.OnHand - item.Reserved;
        return available <= item.ReorderPoint;
    }

    private static int CalculateOrderQuantity(int deficit)
    {
        if (deficit <= 0)
            return 0;
        if (deficit < 10)
            return 10;
        if (deficit < 100)
            return deficit;

        return deficit + 50;
    }

    private static int ApplySeasonalAdjustment(int orderQuantity, int season)
    {
        if (season == 4 && orderQuantity > 0)
            return (int)(orderQuantity * 1.5);
        if (season == 1)
            return orderQuantity / 2;

        return orderQuantity;
    }

    private static string FormatPlanEntry(string sku, int orderQuantity, bool placed)
    {
        if (!placed)
            return $"{sku}:FAILED";
        if (orderQuantity > 200)
            return $"{sku}:LARGE:{orderQuantity}";

        return $"{sku}:{orderQuantity}";
    }
}
